t$::jsonb;
  fixture_slug text := 'anh-trai-vuot-ngan-chong-gai-2026-mo-ban-dot-2';
  event_key integer;
  type_key integer;
  map_key integer;
  item jsonb;
  patch jsonb;
  type_ids jsonb := '{}'::jsonb;
  map_ids jsonb := '{}'::jsonb;
  concert_start timestamptz := GREATEST('2026-12-12 19:00:00+07'::timestamptz, (CURRENT_DATE + 7 + time '19:00') AT TIME ZONE 'Asia/Ho_Chi_Minh');
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(fixture_slug,0));
  SELECT event_id INTO event_key FROM events WHERE slug=fixture_slug;
  IF FOUND THEN RAISE NOTICE 'Queue demo event already exists: %, no rows changed.',event_key; RETURN; END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'types')) THEN RAISE EXCEPTION 'No ticket types in fixture'; END IF;
  patch := jsonb_build_object('slug',fixture_slug,'title','[CONCERT] ANH TRAI VƯỢT NGÀN CHÔNG GAI 2026 - ĐỢT MỞ BÁN 2',
    'starts_at',concert_start,'ends_at',concert_start + interval '4 hours 30 minutes',
    'status','Published','requires_virtual_queue',true,'sales_frozen',false,
    'has_seating_chart',true,'seating_mode','StandingZones',
    'compliance_status','Approved','compliance_version',1,'compliance_reviewed_version',1,'schedule_version',1,
    'sold_tickets',0,'total_tickets',(SELECT SUM((x->>'quantity')::integer) FROM jsonb_array_elements(snapshot->'types') x),
    'view_count',0,'is_deleted',false,'deleted_at',NULL,'deleted_by',NULL,
    'created_at',NOW(),'updated_at',NOW(),'published_at',NOW(),'approved_at',NOW(),'submitted_at',NOW(),
    'reviewed_by',NULL,'updated_by',3,'rejected_at',NULL,'rejected_reason',NULL,
    'poster_public_id',NULL,'banner_public_id',NULL);
  event_key := pg_temp.queue_seed_insert('events',snapshot->'event' || patch);
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'images') LOOP
    PERFORM pg_temp.queue_seed_insert('event_images',item || jsonb_build_object('event_id',event_key,'public_id',NULL,'created_at',NOW()));
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'types') LOOP
    type_key := pg_temp.queue_seed_insert('ticket_types',item || jsonb_build_object('event_id',event_key,'sold_quantity',0,
      'sales_starts_at',NOW()-interval '1 day','sales_ends_at',concert_start-interval '5 hours','status','Active','created_at',NOW(),'updated_at',NOW()));
    type_ids := type_ids || jsonb_build_object(item->>'ticket_type_id',type_key);
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'policies') LOOP
    PERFORM pg_temp.queue_seed_insert('refund_policies',item || jsonb_build_object('event_id',event_key,'created_at',NOW()));
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'maps') LOOP
    map_key := pg_temp.queue_seed_insert('seat_maps',item || jsonb_build_object('event_id',event_key,'created_at',NOW(),'updated_at',NOW()));
    map_ids := map_ids || jsonb_build_object(item->>'seat_map_id',map_key);
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'zones') LOOP
    IF NOT(type_ids ? (item->>'ticket_type_id')) THEN RAISE EXCEPTION 'Unmapped ticket type'; END IF;
    PERFORM pg_temp.queue_seed_insert('seat_zones',item || jsonb_build_object('seat_map_id',(map_ids->>(item->>'seat_map_id'))::integer,
      'ticket_type_id',(type_ids->>(item->>'ticket_type_id'))::integer,'zone_type','Standing'));
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'documents') LOOP
    PERFORM pg_temp.queue_seed_insert('event_compliance_documents',item || jsonb_build_object('event_id',event_key,'version',1,'public_id','','submitted_at',NOW()));
  END LOOP;
  PERFORM pg_temp.queue_seed_insert('event_compliance_reviews',jsonb_build_object('event_id',event_key,'version',1,'decision','Approved',
    'notes','Local queue-demo fixture using existing sample documents. No new manual or legal approval occurred.','reviewed_by',1,'reviewed_at',NOW()));
  PERFORM pg_temp.queue_seed_insert('event_gates',jsonb_build_object('event_id',event_key,'gate_name','Main Gate','description','Standing admission','allowed_ticket_types',NULL,'created_at',NOW()));
  RAISE NOTICE 'Created queue demo event %, slug %',event_key,fixture_slug;
END;
$seed$;
COMMIT;
